beforehash=hashlib.sha256(SOURCE.read_bytes()).hexdigest()
d=Document(SOURCE);old=list(d.paragraphs);changes=[]
normal=deepcopy(old[44]._p.pPr)

def replace(index,text,reason):
 p=old[index];previous=p.text
 assert not p._p.findall('.//'+qn('m:oMath')), 'Do not flatten equations'
 properties=deepcopy(p.runs[0]._r.rPr) if p.runs and p.runs[0]._r.rPr is not None else None
 p.clear();run=p.add_run(text)
 if properties is not None:run._r.insert(0,properties)
 changes.append(dict(operation='replace',original_paragraph=index,old=previous,new=text,reason=reason))

def before(index,text,style='Normal',reason='Verified supplementary results'):
 anchor=old[index];p=anchor.insert_paragraph_before(text,style)
 if style=='Normal':
  if p._p.pPr is not None:p._p.remove(p._p.pPr)
  p._p.insert(0,deepcopy(normal))
 else:
  exemplar=old[64] if style=='Heading 3' else old[112]
  if p._p.pPr is not None:p._p.remove(p._p.pPr)
  p._p.insert(0,deepcopy(exemplar._p.pPr))
 changes.append(dict(operation='insert_before',original_paragraph=index,new=text,style=style,reason=reason))
 return p

